const body = $input.first().json.body || $input.first().json;

// 1. Detect Channel Origin
let channel = 'whatsapp';
if (body.channel) {
  channel = body.channel.toLowerCase();
} else if (body.guild_id || body.channel_id || body.author) {
  channel = 'discord';
} else if (body.update_id || body.message?.chat) {
  channel = 'telegram';
}

// 2. Parse per-channel payloads
let instanceName = body.instance || body.instanceName || 'default_instance';
let isFromMe = false;
let remoteJid = '';
let customerPhone = '';
let customerName = 'Client';
let messageId = body.messageId || body.id || `msg_${Date.now()}`;
let messageText = '';
let isAudio = false;
let audioUrl = '';
let isImage = false;
let imageUrl = '';
let aiEnabled = body.isAiActive ?? body.ai_enabled ?? true;

if (channel === 'whatsapp') {
  if (body.event && body.event !== 'messages.upsert') return [];
  const data = body.data || body;
  const key = data.key || {};
  const message = data.message || {};
  isFromMe = key.fromMe === true;
  remoteJid = key.remoteJid || data.sender || '';
  customerName = data.pushName || 'Client';
  messageId = key.id || messageId;

  if (message.conversation) messageText = message.conversation;
  else if (message.extendedTextMessage?.text) messageText = message.extendedTextMessage.text;
  else if (message.audioMessage) {
    isAudio = true;
    audioUrl = message.audioMessage.url || '';
  } else if (message.imageMessage) {
    isImage = true;
    imageUrl = message.imageMessage.url || '';
    if (message.imageMessage.caption) messageText = message.imageMessage.caption;
  } else if (body.text) {
    messageText = body.text;
  }
  customerPhone = remoteJid.split('@')[0].split(':')[0];
} else if (channel === 'discord') {
  const author = body.author || {};
  isFromMe = Boolean(author.bot || body.isFromMe);
  remoteJid = body.channel_id || body.chatId || '';
  customerName = author.username || 'Discord User';
  customerPhone = author.id || remoteJid;
  messageId = body.id || messageId;
  messageText = body.content || body.text || '';
  if (body.attachments && body.attachments.length > 0) {
    const att = body.attachments[0];
    if (att.content_type?.startsWith('audio/')) {
      isAudio = true;
      audioUrl = att.url;
    } else if (att.content_type?.startsWith('image/')) {
      isImage = true;
      imageUrl = att.url;
    }
  }
} else if (channel === 'telegram') {
  const msg = body.message || body;
  const from = msg.from || {};
  isFromMe = Boolean(from.is_bot || body.isFromMe);
  remoteJid = String(msg.chat?.id || body.chatId || '');
  customerName = from.first_name || 'Telegram User';
  customerPhone = String(from.id || remoteJid);
  messageId = String(msg.message_id || messageId);
  messageText = msg.text || msg.caption || '';
  if (msg.voice || msg.audio) {
    isAudio = true;
    audioUrl = msg.voice?.file_id || msg.audio?.file_id || '';
  } else if (msg.photo && msg.photo.length > 0) {
    isImage = true;
    imageUrl = msg.photo[msg.photo.length - 1].file_id;
  }
}

// Loop prevention & empty guard
if (isFromMe || (!messageText.trim() && !isAudio && !isImage)) {
  return [];
}

return {
  json: {
    channel,
    instance_name: instanceName,
    remote_jid: remoteJid,
    customer_phone: customerPhone,
    customer_name: customerName,
    message_id: messageId,
    message_text: messageText.trim(),
    is_audio: isAudio,
    audio_url: audioUrl,
    is_image: isImage,
    image_url: imageUrl,
    ai_enabled: aiEnabled,
    timestamp: new Date().toISOString()
  }
};

// Smart Typing-Aware Debounced Buffer per sender & channel (Default 3s silence window)
const inbound = $input.first().json;

const textFragments = [inbound.message_text].filter(Boolean);
const aggregatedText = textFragments.join(' ').trim();
const debounceSeconds = (typeof inbound.debounce_seconds === 'number' && inbound.debounce_seconds > 0) ? inbound.debounce_seconds : 3;
const typingSimulation = inbound.typing_simulation_enabled !== false && inbound.realistic_typing !== false;

return {
  json: {
    ...inbound,
    aggregated_text: aggregatedText,
    latest_message_id: inbound.message_id,
    debounce_window_seconds: debounceSeconds,
    typing_simulation_enabled: typingSimulation
  }
};

