const inbound = $('Debounce Sliding Buffer (17s Aggregator)').first().json;
const whisperText = $('Transcribe Voice Note (Whisper Audio-First)').first()?.json?.text || '';
const visionText = $('Context-Aware Vision Analysis (Gemini Flash)').first()?.json?.candidates?.[0]?.content?.parts?.[0]?.text || '';

// Roll 33% chance for random reaction emoji
const rollReaction = Math.random() < 0.33;
const emojis = ['👍', '❤️', '🔥', '👌', '👏'];
const reactionEmoji = rollReaction ? emojis[Math.floor(Math.random() * emojis.length)] : null;

const localTime = new Date().toLocaleString('fr-DZ', {
  timeZone: 'Africa/Algiers',
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
});

const systemPrompt = `You are the authentic Algerian commercial assistant for Chatbot Farm Store.\nROLE & RULES:\n- Respond warmly and helpfully ("khoya", "khti", "saha").\n- If customer writes in Latin Arabizi, reply in authentic Algerian Arabizi with numbers (3, 7, 9).\n- If in Arabic script, reply in Arabic Darija script.\n- If in French, reply in polite French.\n- Use "doka" or "dorka" for now (never derk). Use "lazem" for must. Use "t3ich" for please. Use "chbab/hayel" for great.\n- Delivery across all 58 wilayas via Yalidine (payment on delivery).\n- State prices in DA (e.g. 3500 DA / 350 alf).\n\n[METADATA]\nPlatform: ${inbound.channel.toUpperCase()}\nSender: ${inbound.customer_name} (${inbound.customer_phone})\nTime: ${localTime}\n\n[CUSTOMER QUERY]\nText: ${inbound.aggregated_text || '(none)'}\nSpoken Voice: ${whisperText || '(none)'}\nImage Analysis: ${visionText || '(none)'}`;

return {
  json: {
    system_prompt: systemPrompt,
    user_question: inbound.aggregated_text || whisperText || 'Salam khoya',
    latest_message_id: inbound.latest_message_id,
    channel: inbound.channel,
    customer_phone: inbound.customer_phone,
    remote_jid: inbound.remote_jid,
    instance_name: inbound.instance_name,
    should_react: rollReaction,
    reaction_emoji: reactionEmoji,
    typing_simulation_enabled: inbound.typing_simulation_enabled !== false,
    typing_cadence: inbound.typing_cadence || 'natural'
  }
};

